using VisualTeX.WordVsto;
using Xunit;

namespace VisualTeX.WindowsOffice.Tests;

// Equations exactly as MathType 7.9 stores them, from its own TeX and MathML
// import (the paths its Word commands use). VisualTeX must read each back to
// the formula MathType was given, and write the same formula with the same
// objects, so MathType's renderer draws both the same way.
public sealed class MathTypeOwnStorageConformanceTests
{
    [Theory]
    [InlineData(@"\overline{x}", @"MathML import: COLOR inside the embellishment list", "")]
    [InlineData(@"\dddot{x}", @"embellishment 4", "")]
    [InlineData(@"\ddddot{x}", @"embellishment 24", "")]
    [InlineData(@"\breve{x}", @"embellishment 20", "")]
    [InlineData(@"\underline{x}", @"embellishment 29", "")]
    [InlineData(@"\check{x}", @"limit template, Function caron", "")]
    [InlineData(@"\acute{x}", @"limit template, Function acute", "")]
    [InlineData(@"\grave{x}", @"limit template, Function grave", "")]
    [InlineData(@"\mathring{x}", @"MathML import: limit template, MT Extra ring", "")]
    [InlineData(@"\breve{ab}", @"limit template on a group", "")]
    [InlineData(@"\overbrace{x}", @"brace with an empty label LINE", "")]
    [InlineData(@"\iint", @"lone sign: far-east double integral in symbol size", "")]
    [InlineData(@"\oint", @"lone sign: far-east contour integral in symbol size", "")]
    [InlineData(@"\bigcup", @"lone operator: Symbol union in symbol size", "")]
    [InlineData(@"\bigcap", @"lone operator: Symbol intersection in symbol size", "")]
    [InlineData(@"\overset{a}{b}", @"limit template, upper", "")]
    [InlineData(@"\underset{a}{b}", @"limit template, lower", "")]
    [InlineData(@"a\,b", @"space EF07", "")]
    [InlineData(@"a\!b", @"space EF01", "")]
    [InlineData(@"\max\limits_{x}f", @"MathML import: limit template on a function", "")]
    [InlineData(@"\sum_{i=1}^{n}x_{i}", @"summation template, limits above and below", "")]
    [InlineData(@"\dot{\mathbf{x}}", @"dot on a group: limit template, Function period", "")]
    [InlineData(@"\ddot{\mathbf{r}}", @"double dot on a group: limit template, two periods", "")]
    [InlineData(@"f'", @"prime embellishment 5", "")]
    [InlineData(@"f''", @"double prime embellishment 6", "")]
    [InlineData(@"f'''", @"triple prime embellishment 18", "")]
    [InlineData(@"\alpha'", @"prime embellishment on a Greek letter", "")]
    [InlineData(@"\hbar", @"MT Extra hbar, plain style", "")]
    [InlineData(@"\tfrac{a}{b}", @"small fraction: variation 1, script-size slots", "")]
    public void ReadsTheFormulaMathTypeStored(string latex, string note, string mathTypeMtef)
    {
        var mathMl = MathTypeMtefCodec.ReadEquationNativeMathMl(Native(Convert.FromBase64String(mathTypeMtef)));
        Assert.True(latex == MathMlToLatexConverter.Convert(mathMl), note + ": " + mathMl);
    }

