    public void WritesMathTypesOwnStructure(string note, string mathMl, string mathTypeMtef)
    {
        var mathType = Convert.FromBase64String(mathTypeMtef);
        var visualTex = MathTypeMtefCodec.CreateEquationNativeAtFontSize(mathMl, false, 12).Mtef;
        Assert.True(Structure(mathType) == Structure(visualTex), note + "\nMathType:  " + Structure(mathType) + "\nVisualTeX: " + Structure(visualTex));
    }

    private static byte[] Native(byte[] mtef)
    {
        var seed = MathTypeMtefCodec.CreateEquationNative("<math><mi>x</mi></math>", false);
        var native = seed.EquationNative.Take(28).Concat(mtef).ToArray();
        Buffer.BlockCopy(BitConverter.GetBytes((uint)mtef.Length), 0, native, 8, 4);
        return native;
    }

    // The root's objects, embellishments and size records, one token each,
    // without colour, private (FUTURE) and definition records, which change
    // neither what MathType draws nor where.
    private static string Structure(byte[] mtef)
    {
        var position = MathTypeMtefCodec.FindRootStructureOffset(mtef);
        var tokens = new List<string>();
        int Unsigned()
        {
            var value = mtef[position++];
            return value < 0xFF ? value : mtef[position++] | mtef[position++] << 8;
        }
        void Nudge(byte options)
        {
            if ((options & 0x08) == 0) return;
            var dx = mtef[position++];
            var dy = mtef[position++];
            if (dx == 128 && dy == 128) position += 4;
        }
        void Ruler()
        {
            if (mtef[position] == 7) position++;
            position += 1 + mtef[position] * 3;
        }
        void SkipString()
        {
            while (mtef[position++] != 0) { }
        }
        void List()
        {
            while (mtef[position] != 0) Record();
            position++;
            tokens.Add(")");
        }
        void Record()
        {
            var record = mtef[position++];
            switch (record)
            {
                case 1:
                {
                    var options = mtef[position++];
                    Nudge(options);
                    if ((options & 0x04) != 0) position += 2;
                    if ((options & 0x02) != 0) Ruler();
                    if ((options & 0x01) != 0)
                    {
                        tokens.Add("L-");
                        return;
                    }
                    tokens.Add("L(");
                    List();
                    return;
                }
                case 2:
                {
                    var options = mtef[position++];
                    Nudge(options);
                    var lead = mtef[position++];
                    var typeface = lead == 0xFF ? (mtef[position++] | mtef[position++] << 8) - 32768 : lead - 128;
                    var text = "C" + typeface;
                    if ((options & 0x20) == 0)
                    {
                        text += ":" + (mtef[position] | mtef[position + 1] << 8).ToString("X4");
                        position += 2;
                    }
                    if ((options & 0x04) != 0) text += "/" + mtef[position++].ToString("X2");
                    if ((options & 0x10) != 0)
                    {
                        text += "/" + (mtef[position] | mtef[position + 1] << 8).ToString("X4");
                        position += 2;
                    }
                    if ((options & 0x01) != 0)
                    {
                        while (mtef[position] != 0)
                        {
                            if (mtef[position++] == 15)
                            {
                                Unsigned();
                                continue;
                            }
                            var embellishmentOptions = mtef[position++];
                            Nudge(embellishmentOptions);
                            text += "+e" + mtef[position++];
                        }
                        position++;
                    }
                    tokens.Add(text);
                    return;
                }
                case 3:
                {
                    var options = mtef[position++];
                    Nudge(options);
                    var selector = mtef[position++];
                    int variation = mtef[position++];
                    if ((variation & 0x80) != 0) variation = (variation & 0x7F) | mtef[position++] << 8;
                    position++;
                    tokens.Add("T" + selector + "/" + variation.ToString("X") + "(");
                    List();
                    return;
                }
                case 4:
                {
                    var options = mtef[position++];
                    Nudge(options);
                    var alignment = mtef[position++] + "," + mtef[position++];
                    if ((options & 0x02) != 0) Ruler();
                    tokens.Add("P" + alignment + "(");
                    List();
                    return;
                }
                case 5:
                {
                    var options = mtef[position++];
                    Nudge(options);
                    position += 3;
                    var rows = mtef[position++];
                    var columns = mtef[position++];
                    position += Math.Max(1, (rows + 4) / 4) + Math.Max(1, (columns + 4) / 4);
                    tokens.Add("M" + rows + "x" + columns + "(");
                    List();
                    return;
                }
                case 7:
                    position--;
                    Ruler();
                    return;
                case 8:
                    Unsigned();
                    position++;
                    return;
                case 9:
                {
                    var form = mtef[position++];
                    position += form == 101 ? 2 : form == 100 ? 3 : 1;
                    tokens.Add("SIZE");
                    return;
                }
                case >= 10 and <= 14:
                    tokens.Add(record switch { 10 => "FULL", 11 => "SUB", 12 => "SUB2", 13 => "SYM", _ => "SUBSYM" });
                    return;
                case 15:
                    Unsigned();
                    return;
                case 16:
                {
                    var options = mtef[position++];
                    position += (options & 0x01) != 0 ? 8 : 6;
                    if ((options & 0x04) != 0) SkipString();
                    return;
                }
                case 17:
                    Unsigned();
                    SkipString();
                    return;
                case 19:
                    SkipString();
                    return;
                case >= 100:
                {
                    var length = Unsigned();
                    position += length;
                    return;
                }
                default:
                    throw new InvalidDataException("MTEF record " + record + " at " + (position - 1));
            }
        }
        Record();
        return string.Join(" ", tokens);
    }
}
